(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.03+sy*0.02+t*0.5)*8;
  const w2y = Math.cos(sx*0.02-sy*0.03+t*0.4)*8;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,1.8],
    [400+Math.cos(t*0.55+2)*60,220+Math.sin(t*0.75+4)*40,0.085,2.1],
    [200+Math.sin(t*0.25+6)*110,60+Math.cos(t*0.45+5)*80,0.075,2.4],
    [300+Math.cos(t*0.7+0.5)*90,30+Math.sin(t*0.5+2.5)*60,0.095,1.6]
  ];
  let aS=0,iS=0,mS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    mS+=Math.sin(d*f*1.3-t*sp*0.8+0.7);
  }
  const act=aS/10,inh=iS/10,mod=mS/10;
  const bg=(Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2
    +Math.sin((fx+fy)*0.12+t*2.5)*0.2+Math.sin((fx-fy)*0.1-t*2)*0.2
    +Math.sin(fx*0.07+fy*0.05+t*1.8)*0.15;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2);
  const ang=Math.atan2(fy-cy,fx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.08-ang*2+t*0.9)*0.2;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+mod*0.2)*2.2);
  const cell=Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(fx*0.4+fy*0.3+t*3)*Math.sin(fx*0.35-fy*0.25-t*2.5)*0.12;
  const pulse=Math.sin(dist*0.03-t*1.2)*0.18*Math.exp(-dist*0.005);
  const blend=reaction*0.58+cell*0.2+micro+pulse;
  const v=blend*0.5+0.5;
  const pal=[
    [5,10,48],[8,32,78],[12,62,105],[18,98,118],[25,138,118],
    [60,170,105],[130,195,75],[195,195,55],[225,165,50],
    [218,115,55],[192,68,52],[155,38,58],[105,24,52],
    [62,16,48],[30,12,48],[5,10,48]
  ];
  const idx=v*(pal.length-1);
  const i=Math.min(idx|0,pal.length-2);
  const f=idx-i;
  const lum=0.78+Math.sin(reaction*Math.PI)*0.22;
  const edge=Math.abs(reaction)>0.7?1.18:1.0;
  const vig=0.82+0.18*Math.exp(-dist*0.003);
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*vig)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*vig)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*vig)|0
  ];
}
